-- =====================================================================================
-- Catalogue de démonstration : prestations, prix pose seule et composition en pièces.
--
-- Règles de prix, taux horaire de 78,65 € TVA comprise (65,00 € hors TVA, celui de V907) :
--   forfait     pièces de la composition au prix du catalogue, plus la durée au taux
--               horaire, arrondi à l'euro inférieur. Un forfait n'est jamais plus cher que
--               les mêmes pièces et le même temps facturés à part.
--   pose seule  durée au taux horaire, arrondie à l'euro supérieur, plus 10,00 € de
--               contrôle des pièces apportées, proposée seulement quand les pièces de la
--               composition valent plus de 20,00 €. Pièces plus pose seule, puis forfait,
--               puis pose seule, dans cet ordre strict (GraineDemonstrationIT).
--   sans pièces jamais sous la durée au taux horaire.
-- Les disques et plaquettes arrière sont à 231,00 € : la règle donne 232,00 €, qu'aucun prix
-- hors TVA à deux décimales ne redonne exactement.
--
-- Les prestations de V16 gardent leur code (les rendez-vous et interventions de la graine
-- les référencent). V16 reste intacte : seule la démonstration change leurs textes et
-- leurs prix. La main-d'œuvre à l'heure de V907 n'est pas touchée.
--
-- Traductions écrites par le développeur, à relire par un locuteur.
-- =====================================================================================

UPDATE service s
SET categorie_id = c.id, libelle = v.fr, libelle_nl = v.nl, libelle_en = v.en, description = v.dfr,
    description_nl = v.dnl, description_en = v.den, duree_minutes = v.duree, prix_htva = v.prix,
    prix_pose_seule_htva = v.pose, taux_tva = 21.00, updated_by = 'demo'
FROM (VALUES
          ('VIDANGE_STD', 'ENTRETIEN', 'Vidange moteur, huile et filtre', 'Olieverversing, olie en filter', 'Engine oil and filter change', 'L''huile usagée est vidangée et remplacée par une huile adaptée à votre moteur. Le filtre à huile et le joint du bouchon sont changés à chaque fois. Les niveaux et les fuites visibles sont contrôlés.', 'De oude olie wordt afgetapt en vervangen door een olie die bij uw motor past. Oliefilter en afdichtring van de aftapplug worden telkens vervangen. Peilen en zichtbare lekken worden gecontroleerd.', 'The used oil is drained and replaced with an oil suited to your engine. The oil filter and drain plug washer are changed every time. Fluid levels and visible leaks are checked.', 30, 77.69, 41.32),
          ('REVISION_ANNUELLE', 'ENTRETIEN', 'Révision annuelle', 'Jaarlijkse onderhoudsbeurt', 'Annual service', 'Vidange, remplacement des filtres à huile, à air et d''habitacle, et contrôle de trente points de sécurité. Le compte rendu indique ce qui devra être prévu au prochain passage.', 'Olieverversing, vervanging van olie-, lucht- en interieurfilter, en controle van dertig veiligheidspunten. Het verslag vermeldt wat bij het volgende bezoek gepland moet worden.', 'Oil change, replacement of the oil, air and cabin filters, and a thirty-point safety check. The report says what to plan for the next visit.', 90, 176.86, 106.61),
          ('REVISION_COMPLETE', 'ENTRETIEN', 'Révision complète avec filtre à carburant', 'Volledige onderhoudsbeurt met brandstoffilter', 'Full service with fuel filter', 'La révision annuelle, complétée du remplacement du filtre à carburant. Recommandée tous les deux ans ou selon le carnet du constructeur.', 'De jaarlijkse onderhoudsbeurt, aangevuld met de vervanging van de brandstoffilter. Aanbevolen om de twee jaar of volgens het onderhoudsboekje.', 'The annual service plus replacement of the fuel filter. Recommended every two years or as the service book says.', 120, 238.84, 138.84),
          ('FILTRE_AIR', 'ENTRETIEN', 'Remplacement du filtre à air', 'Vervanging van de luchtfilter', 'Air filter replacement', 'Un filtre à air encrassé fait perdre de la puissance et augmente la consommation. Le filtre est remplacé et le boîtier nettoyé.', 'Een vuile luchtfilter kost vermogen en verhoogt het verbruik. De filter wordt vervangen en de behuizing gereinigd.', 'A clogged air filter costs power and raises fuel consumption. The filter is replaced and the housing cleaned.', 20, 39.67, 30.58),
          ('FILTRE_HABITACLE', 'ENTRETIEN', 'Remplacement du filtre d''habitacle', 'Vervanging van de interieurfilter', 'Cabin filter replacement', 'Le filtre d''habitacle retient pollens et poussières avant qu''ils n''entrent dans la voiture. Le remplacer chaque année garde l''air intérieur sain et évite la buée.', 'De interieurfilter houdt pollen en stof tegen voor ze de auto binnenkomen. Een jaarlijkse vervanging houdt de lucht gezond en voorkomt aangedampte ruiten.', 'The cabin filter stops pollen and dust before they enter the car. Replacing it every year keeps the air healthy and prevents misting.', 20, 38.02, NULL::NUMERIC),
          ('BOUGIES', 'ENTRETIEN', 'Remplacement des bougies d''allumage', 'Vervanging van de bougies', 'Spark plug replacement', 'Les quatre bougies d''un moteur essence sont remplacées et serrées au couple prévu. Des bougies usées causent des démarrages difficiles et des ratés.', 'De vier bougies van een benzinemotor worden vervangen en met het voorgeschreven koppel aangehaald. Versleten bougies geven moeilijk starten en overslaan.', 'The four spark plugs of a petrol engine are replaced and tightened to the specified torque. Worn plugs cause hard starting and misfires.', 45, 80.99, 57.85),
          ('LIQUIDE_REFROIDISSEMENT', 'ENTRETIEN', 'Vidange du liquide de refroidissement', 'Verversing van de koelvloeistof', 'Coolant change', 'Le circuit est vidangé, rincé puis rempli d''un liquide neuf, et purgé de son air. Un liquide trop ancien protège mal du gel et de la corrosion.', 'Het circuit wordt afgetapt, gespoeld, met nieuwe vloeistof gevuld en ontlucht. Te oude vloeistof beschermt slecht tegen vorst en corrosie.', 'The system is drained, flushed, refilled with new coolant and bled of air. Old coolant protects poorly against frost and corrosion.', 60, 93.39, 73.55),
          ('PURGE_FREIN', 'FREINAGE', 'Purge du liquide de frein', 'Verversing van de remvloeistof', 'Brake fluid change', 'Le liquide de frein absorbe l''humidité avec le temps et perd de son efficacité. Il est remplacé roue par roue, puis le freinage est essayé.', 'Remvloeistof neemt na verloop van tijd vocht op en wordt minder doeltreffend. Ze wordt wiel per wiel vervangen, daarna worden de remmen getest.', 'Brake fluid absorbs moisture over time and loses its effectiveness. It is replaced wheel by wheel, then the brakes are tested.', 45, 60.33, NULL::NUMERIC),
          ('PLAQUETTES_AV', 'FREINAGE', 'Remplacement des plaquettes avant', 'Vervanging van de remblokken vooraan', 'Front brake pad replacement', 'Les plaquettes avant sont remplacées et les étriers nettoyés. L''épaisseur des disques est mesurée pour vous dire s''ils peuvent encore servir.', 'De remblokken vooraan worden vervangen en de remklauwen gereinigd. De dikte van de schijven wordt gemeten om te zeggen of ze nog mee kunnen.', 'The front pads are replaced and the callipers cleaned. Disc thickness is measured to tell you whether the discs can stay.', 45, 89.26, 57.85),
          ('PLAQUETTES_AR', 'FREINAGE', 'Remplacement des plaquettes arrière', 'Vervanging van de remblokken achteraan', 'Rear brake pad replacement', 'Remplacement des plaquettes arrière et contrôle du frein à main. Les disques ou tambours sont mesurés.', 'Vervanging van de remblokken achteraan en controle van de handrem. Schijven of trommels worden gemeten.', 'Rear pad replacement and handbrake check. Discs or drums are measured.', 45, 79.34, 57.85),
          ('DISQUES_PLAQUETTES_AV', 'FREINAGE', 'Disques et plaquettes avant', 'Remschijven en remblokken vooraan', 'Front discs and pads', 'Les deux disques et les plaquettes de l''essieu avant sont remplacés ensemble, comme le prévoit le constructeur. Un essai sur route termine le travail.', 'De twee schijven en de remblokken van de vooras worden samen vervangen, zoals de constructeur voorschrijft. Een proefrit sluit het werk af.', 'Both discs and the pads on the front axle are replaced together, as the manufacturer specifies. A road test completes the job.', 90, 212.40, 106.61),
          ('DISQUES_PLAQUETTES_AR', 'FREINAGE', 'Disques et plaquettes arrière', 'Remschijven en remblokken achteraan', 'Rear discs and pads', 'Remplacement des disques et des plaquettes de l''essieu arrière, puis réglage du frein à main.', 'Vervanging van de schijven en remblokken van de achteras, daarna afstelling van de handrem.', 'Replacement of the rear discs and pads, followed by handbrake adjustment.', 90, 190.91, 106.61),
          ('CONTROLE_FREINAGE', 'FREINAGE', 'Contrôle du freinage', 'Controle van de remmen', 'Brake check', 'Mesure de l''usure des plaquettes et des disques, état des flexibles et du liquide. Vous savez ce qui est à prévoir, sans engagement.', 'Meting van de slijtage van remblokken en schijven, staat van remslangen en remvloeistof. U weet wat er te plannen is, zonder verplichting.', 'Measurement of pad and disc wear, condition of hoses and fluid. You know what to plan, with no commitment.', 20, 23.97, NULL::NUMERIC),
          ('MONTAGE_PNEU', 'PNEUMATIQUE', 'Montage et équilibrage d''un pneu', 'Montage en balanceren van een band', 'Fitting and balancing one tyre', 'Démontage de l''ancien pneu, montage du neuf avec une valve neuve, puis équilibrage de la roue. Le prix s''entend par pneu.', 'Demontage van de oude band, montage van de nieuwe met een nieuw ventiel, daarna balanceren van het wiel. De prijs geldt per band.', 'Removal of the old tyre, fitting of the new one with a new valve, then wheel balancing. The price is per tyre.', 15, 18.18, NULL::NUMERIC),
          ('PERMUTATION_PNEUS', 'PNEUMATIQUE', 'Permutation des quatre pneus', 'Wisselen van de vier banden', 'Rotation of all four tyres', 'Les roues avant et arrière sont échangées pour une usure régulière. Les pressions sont réglées à la valeur du constructeur.', 'De voor- en achterwielen worden verwisseld voor een gelijkmatige slijtage. De spanning wordt op de waarde van de constructeur gezet.', 'Front and rear wheels are swapped for even wear. Pressures are set to the manufacturer''s value.', 30, 39.67, NULL::NUMERIC),
          ('CHANGEMENT_ROUES', 'PNEUMATIQUE', 'Changement saisonnier des quatre roues', 'Seizoenswissel van de vier wielen', 'Seasonal change of all four wheels', 'Pose de vos roues d''été ou d''hiver, serrage au couple et réglage des pressions. Les roues déposées vous sont rendues propres.', 'Montage van uw zomer- of winterwielen, aanhalen met het juiste koppel en afstellen van de spanning. De gedemonteerde wielen krijgt u proper terug.', 'Fitting of your summer or winter wheels, torque tightening and pressure setting. The removed wheels are returned to you clean.', 45, 48.76, NULL::NUMERIC),
          ('CREVAISON', 'PNEUMATIQUE', 'Réparation d''une crevaison', 'Herstelling van een lekke band', 'Puncture repair', 'Le pneu est démonté et réparé par l''intérieur quand la perforation le permet. Sinon, nous vous proposons un remplacement.', 'De band wordt gedemonteerd en van binnenuit hersteld als het gat dat toelaat. Anders stellen we een vervanging voor.', 'The tyre is removed and repaired from the inside when the puncture allows it. Otherwise we suggest a replacement.', 25, 28.10, NULL::NUMERIC),
          ('GEOMETRIE', 'PNEUMATIQUE', 'Géométrie et parallélisme', 'Uitlijning', 'Wheel alignment', 'Réglage des angles des roues avant au banc. Une géométrie juste évite l''usure inégale des pneus et une voiture qui tire d''un côté.', 'Afstelling van de hoeken van de voorwielen op de testbank. Een juiste uitlijning voorkomt ongelijke bandenslijtage en een wagen die naar één kant trekt.', 'Front wheel angles are set on the alignment bench. Correct alignment prevents uneven tyre wear and a car that pulls to one side.', 60, 73.55, NULL::NUMERIC),
          ('DIAG_ELEC', 'DIAGNOSTIC', 'Diagnostic électronique', 'Elektronische diagnose', 'Electronic diagnosis', 'Lecture des codes défaut de tous les calculateurs, explication de chaque défaut et devis si une réparation s''impose.', 'Uitlezen van de foutcodes van alle rekeneenheden, uitleg bij elke fout en een offerte als een herstelling nodig is.', 'Reading of fault codes from all control units, an explanation of each fault and a quote if a repair is needed.', 30, 53.72, NULL::NUMERIC),
          ('CONTROLE_BATTERIE', 'DIAGNOSTIC', 'Contrôle de la batterie et du circuit de charge', 'Controle van accu en laadcircuit', 'Battery and charging system check', 'Test de la batterie, de l''alternateur et du démarreur. Utile avant l''hiver ou après des démarrages difficiles.', 'Test van accu, dynamo en startmotor. Nuttig voor de winter of na moeilijk starten.', 'Test of the battery, alternator and starter motor. Useful before winter or after hard starting.', 15, 20.66, NULL::NUMERIC),
          ('REMPLACEMENT_BATTERIE', 'DIAGNOSTIC', 'Remplacement de la batterie', 'Vervanging van de accu', 'Battery replacement', 'Pose d''une batterie neuve de 72 Ah et contrôle du circuit de charge. L''ancienne batterie reste au garage, qui la confie à la filière de reprise.', 'Plaatsing van een nieuwe accu van 72 Ah en controle van het laadcircuit. De oude accu blijft in de garage, die ze aan de inzamelketen toevertrouwt.', 'Fitting of a new 72 Ah battery and a charging system check. The old battery stays at the garage, which hands it over for recycling.', 30, 138.84, 41.32),
          ('AMPOULES_PHARES', 'DIAGNOSTIC', 'Remplacement des ampoules de phares', 'Vervanging van de koplamplampen', 'Headlight bulb replacement', 'Les deux ampoules de feux de croisement sont remplacées, puis la hauteur des faisceaux est contrôlée.', 'De twee dimlichtlampen worden vervangen, daarna wordt de hoogte van de lichtbundels gecontroleerd.', 'Both dipped beam bulbs are replaced, then the beam height is checked.', 30, 44.63, NULL::NUMERIC),
          ('BALAIS_ESSUIE_GLACE', 'DIAGNOSTIC', 'Remplacement des balais d''essuie-glace', 'Vervanging van de ruitenwisserbladen', 'Wiper blade replacement', 'Pose de balais avant neufs adaptés à votre pare-brise. Des balais usés laissent des traînées et font du bruit.', 'Plaatsing van nieuwe wisserbladen vooraan die bij uw voorruit passen. Versleten bladen laten strepen na en maken lawaai.', 'Fitting of new front blades suited to your windscreen. Worn blades leave streaks and make noise.', 15, 39.67, 24.79),
          ('RECHARGE_CLIM', 'CLIMATISATION', 'Recharge de la climatisation', 'Bijvullen van de airco', 'Air conditioning recharge', 'Récupération du fluide, contrôle de l''étanchéité du circuit et recharge à la quantité prévue par le constructeur.', 'Opvangen van het koelmiddel, controle van de dichtheid van het circuit en bijvullen tot de hoeveelheid van de constructeur.', 'Recovery of the refrigerant, a leak check of the system and recharge to the manufacturer''s quantity.', 60, 98.35, NULL::NUMERIC),
          ('DESINFECTION_CLIM', 'CLIMATISATION', 'Désinfection du circuit de climatisation', 'Ontsmetting van het aircocircuit', 'Air conditioning disinfection', 'Traitement du circuit et de l''évaporateur contre les bactéries et les mauvaises odeurs. Conseillée une fois par an.', 'Behandeling van het circuit en de verdamper tegen bacteriën en slechte geuren. Eén keer per jaar aangeraden.', 'Treatment of the system and evaporator against bacteria and bad smells. Recommended once a year.', 30, 39.67, NULL::NUMERIC),
          ('KIT_DISTRIBUTION', 'MOTEUR', 'Remplacement du kit de distribution', 'Vervanging van de distributieset', 'Timing belt kit replacement', 'Courroie, galets et pompe à eau sont remplacés ensemble, aux intervalles du constructeur. Une courroie qui casse peut détruire le moteur.', 'Riem, rollen en waterpomp worden samen vervangen, volgens de intervallen van de constructeur. Een riem die breekt kan de motor vernielen.', 'Belt, pulleys and water pump are replaced together at the manufacturer''s intervals. A broken belt can destroy the engine.', 240, 474.38, 269.42),
          ('EMBRAYAGE', 'MOTEUR', 'Remplacement de l''embrayage', 'Vervanging van de koppeling', 'Clutch replacement', 'Disque, mécanisme et butée sont remplacés. À envisager quand la pédale devient dure ou que l''embrayage patine.', 'Plaat, drukgroep en druklager worden vervangen. Te overwegen als het pedaal zwaar wordt of de koppeling slipt.', 'Disc, pressure plate and release bearing are replaced. Worth considering when the pedal gets heavy or the clutch slips.', 300, 564.46, 334.71),
          ('RETOUCHE_PEINTURE', 'CARROSSERIE', 'Retouche de peinture', 'Lakherstelling', 'Paint touch-up', 'Rayure ou éclat de peinture traité localement, à la teinte de votre voiture. Le prix vaut pour une zone de la taille d''une main.', 'Kras of lakschade plaatselijk hersteld, in de kleur van uw wagen. De prijs geldt voor een zone ter grootte van een hand.', 'A scratch or chip is treated locally, matched to your car''s colour. The price covers an area the size of a hand.', 60, 90.08, NULL::NUMERIC),
          ('RENOVATION_OPTIQUES', 'CARROSSERIE', 'Rénovation des optiques de phares', 'Renovatie van de koplampen', 'Headlight restoration', 'Les optiques jaunies sont poncées, polies puis protégées. L''éclairage retrouve sa portée.', 'Vergeelde koplampen worden geschuurd, gepolijst en beschermd. De verlichting krijgt haar bereik terug.', 'Yellowed headlight lenses are sanded, polished and protected. The lights regain their reach.', 45, 56.20, NULL::NUMERIC),
          ('PREPARATION_CT', 'CT', 'Préparation au contrôle technique', 'Voorbereiding op de keuring', 'MOT preparation', 'Les points vérifiés au contrôle technique sont passés en revue avant votre rendez-vous. Vous savez ce qui doit être corrigé pour ne pas devoir y retourner.', 'De punten die op de keuring gecontroleerd worden, worden vooraf nagekeken. U weet wat hersteld moet worden om niet terug te moeten.', 'The points checked at the roadworthiness test are reviewed before your appointment. You know what to fix so you do not have to go back.', 30, 44.63, NULL::NUMERIC)
     ) AS v(code, cat, fr, nl, en, dfr, dnl, den, duree, prix, pose)
         JOIN categorie c ON c.code = v.cat
WHERE s.code = v.code
  AND (s.updated_by IS NULL OR s.updated_by = 'demo');

INSERT INTO service (categorie_id, code, libelle, libelle_nl, libelle_en, description, description_nl, description_en,
                     duree_minutes, prix_htva, prix_pose_seule_htva, taux_tva, created_by, updated_by)
SELECT c.id, v.code, v.fr, v.nl, v.en, v.dfr, v.dnl, v.den, v.duree, v.prix, v.pose, 21.00, 'demo', 'demo'
FROM (VALUES
          ('VIDANGE_STD', 'ENTRETIEN', 'Vidange moteur, huile et filtre', 'Olieverversing, olie en filter', 'Engine oil and filter change', 'L''huile usagée est vidangée et remplacée par une huile adaptée à votre moteur. Le filtre à huile et le joint du bouchon sont changés à chaque fois. Les niveaux et les fuites visibles sont contrôlés.', 'De oude olie wordt afgetapt en vervangen door een olie die bij uw motor past. Oliefilter en afdichtring van de aftapplug worden telkens vervangen. Peilen en zichtbare lekken worden gecontroleerd.', 'The used oil is drained and replaced with an oil suited to your engine. The oil filter and drain plug washer are changed every time. Fluid levels and visible leaks are checked.', 30, 77.69, 41.32),
          ('REVISION_ANNUELLE', 'ENTRETIEN', 'Révision annuelle', 'Jaarlijkse onderhoudsbeurt', 'Annual service', 'Vidange, remplacement des filtres à huile, à air et d''habitacle, et contrôle de trente points de sécurité. Le compte rendu indique ce qui devra être prévu au prochain passage.', 'Olieverversing, vervanging van olie-, lucht- en interieurfilter, en controle van dertig veiligheidspunten. Het verslag vermeldt wat bij het volgende bezoek gepland moet worden.', 'Oil change, replacement of the oil, air and cabin filters, and a thirty-point safety check. The report says what to plan for the next visit.', 90, 176.86, 106.61),
          ('REVISION_COMPLETE', 'ENTRETIEN', 'Révision complète avec filtre à carburant', 'Volledige onderhoudsbeurt met brandstoffilter', 'Full service with fuel filter', 'La révision annuelle, complétée du remplacement du filtre à carburant. Recommandée tous les deux ans ou selon le carnet du constructeur.', 'De jaarlijkse onderhoudsbeurt, aangevuld met de vervanging van de brandstoffilter. Aanbevolen om de twee jaar of volgens het onderhoudsboekje.', 'The annual service plus replacement of the fuel filter. Recommended every two years or as the service book says.', 120, 238.84, 138.84),
          ('FILTRE_AIR', 'ENTRETIEN', 'Remplacement du filtre à air', 'Vervanging van de luchtfilter', 'Air filter replacement', 'Un filtre à air encrassé fait perdre de la puissance et augmente la consommation. Le filtre est remplacé et le boîtier nettoyé.', 'Een vuile luchtfilter kost vermogen en verhoogt het verbruik. De filter wordt vervangen en de behuizing gereinigd.', 'A clogged air filter costs power and raises fuel consumption. The filter is replaced and the housing cleaned.', 20, 39.67, 30.58),
          ('FILTRE_HABITACLE', 'ENTRETIEN', 'Remplacement du filtre d''habitacle', 'Vervanging van de interieurfilter', 'Cabin filter replacement', 'Le filtre d''habitacle retient pollens et poussières avant qu''ils n''entrent dans la voiture. Le remplacer chaque année garde l''air intérieur sain et évite la buée.', 'De interieurfilter houdt pollen en stof tegen voor ze de auto binnenkomen. Een jaarlijkse vervanging houdt de lucht gezond en voorkomt aangedampte ruiten.', 'The cabin filter stops pollen and dust before they enter the car. Replacing it every year keeps the air healthy and prevents misting.', 20, 38.02, NULL::NUMERIC),
          ('BOUGIES', 'ENTRETIEN', 'Remplacement des bougies d''allumage', 'Vervanging van de bougies', 'Spark plug replacement', 'Les quatre bougies d''un moteur essence sont remplacées et serrées au couple prévu. Des bougies usées causent des démarrages difficiles et des ratés.', 'De vier bougies van een benzinemotor worden vervangen en met het voorgeschreven koppel aangehaald. Versleten bougies geven moeilijk starten en overslaan.', 'The four spark plugs of a petrol engine are replaced and tightened to the specified torque. Worn plugs cause hard starting and misfires.', 45, 80.99, 57.85),
          ('LIQUIDE_REFROIDISSEMENT', 'ENTRETIEN', 'Vidange du liquide de refroidissement', 'Verversing van de koelvloeistof', 'Coolant change', 'Le circuit est vidangé, rincé puis rempli d''un liquide neuf, et purgé de son air. Un liquide trop ancien protège mal du gel et de la corrosion.', 'Het circuit wordt afgetapt, gespoeld, met nieuwe vloeistof gevuld en ontlucht. Te oude vloeistof beschermt slecht tegen vorst en corrosie.', 'The system is drained, flushed, refilled with new coolant and bled of air. Old coolant protects poorly against frost and corrosion.', 60, 93.39, 73.55),
          ('PURGE_FREIN', 'FREINAGE', 'Purge du liquide de frein', 'Verversing van de remvloeistof', 'Brake fluid change', 'Le liquide de frein absorbe l''humidité avec le temps et perd de son efficacité. Il est remplacé roue par roue, puis le freinage est essayé.', 'Remvloeistof neemt na verloop van tijd vocht op en wordt minder doeltreffend. Ze wordt wiel per wiel vervangen, daarna worden de remmen getest.', 'Brake fluid absorbs moisture over time and loses its effectiveness. It is replaced wheel by wheel, then the brakes are tested.', 45, 60.33, NULL::NUMERIC),
          ('PLAQUETTES_AV', 'FREINAGE', 'Remplacement des plaquettes avant', 'Vervanging van de remblokken vooraan', 'Front brake pad replacement', 'Les plaquettes avant sont remplacées et les étriers nettoyés. L''épaisseur des disques est mesurée pour vous dire s''ils peuvent encore servir.', 'De remblokken vooraan worden vervangen en de remklauwen gereinigd. De dikte van de schijven wordt gemeten om te zeggen of ze nog mee kunnen.', 'The front pads are replaced and the callipers cleaned. Disc thickness is measured to tell you whether the discs can stay.', 45, 89.26, 57.85),
          ('PLAQUETTES_AR', 'FREINAGE', 'Remplacement des plaquettes arrière', 'Vervanging van de remblokken achteraan', 'Rear brake pad replacement', 'Remplacement des plaquettes arrière et contrôle du frein à main. Les disques ou tambours sont mesurés.', 'Vervanging van de remblokken achteraan en controle van de handrem. Schijven of trommels worden gemeten.', 'Rear pad replacement and handbrake check. Discs or drums are measured.', 45, 79.34, 57.85),
          ('DISQUES_PLAQUETTES_AV', 'FREINAGE', 'Disques et plaquettes avant', 'Remschijven en remblokken vooraan', 'Front discs and pads', 'Les deux disques et les plaquettes de l''essieu avant sont remplacés ensemble, comme le prévoit le constructeur. Un essai sur route termine le travail.', 'De twee schijven en de remblokken van de vooras worden samen vervangen, zoals de constructeur voorschrijft. Een proefrit sluit het werk af.', 'Both discs and the pads on the front axle are replaced together, as the manufacturer specifies. A road test completes the job.', 90, 212.40, 106.61),
          ('DISQUES_PLAQUETTES_AR', 'FREINAGE', 'Disques et plaquettes arrière', 'Remschijven en remblokken achteraan', 'Rear discs and pads', 'Remplacement des disques et des plaquettes de l''essieu arrière, puis réglage du frein à main.', 'Vervanging van de schijven en remblokken van de achteras, daarna afstelling van de handrem.', 'Replacement of the rear discs and pads, followed by handbrake adjustment.', 90, 190.91, 106.61),
          ('CONTROLE_FREINAGE', 'FREINAGE', 'Contrôle du freinage', 'Controle van de remmen', 'Brake check', 'Mesure de l''usure des plaquettes et des disques, état des flexibles et du liquide. Vous savez ce qui est à prévoir, sans engagement.', 'Meting van de slijtage van remblokken en schijven, staat van remslangen en remvloeistof. U weet wat er te plannen is, zonder verplichting.', 'Measurement of pad and disc wear, condition of hoses and fluid. You know what to plan, with no commitment.', 20, 23.97, NULL::NUMERIC),
          ('MONTAGE_PNEU', 'PNEUMATIQUE', 'Montage et équilibrage d''un pneu', 'Montage en balanceren van een band', 'Fitting and balancing one tyre', 'Démontage de l''ancien pneu, montage du neuf avec une valve neuve, puis équilibrage de la roue. Le prix s''entend par pneu.', 'Demontage van de oude band, montage van de nieuwe met een nieuw ventiel, daarna balanceren van het wiel. De prijs geldt per band.', 'Removal of the old tyre, fitting of the new one with a new valve, then wheel balancing. The price is per tyre.', 15, 18.18, NULL::NUMERIC),
          ('PERMUTATION_PNEUS', 'PNEUMATIQUE', 'Permutation des quatre pneus', 'Wisselen van de vier banden', 'Rotation of all four tyres', 'Les roues avant et arrière sont échangées pour une usure régulière. Les pressions sont réglées à la valeur du constructeur.', 'De voor- en achterwielen worden verwisseld voor een gelijkmatige slijtage. De spanning wordt op de waarde van de constructeur gezet.', 'Front and rear wheels are swapped for even wear. Pressures are set to the manufacturer''s value.', 30, 39.67, NULL::NUMERIC),
          ('CHANGEMENT_ROUES', 'PNEUMATIQUE', 'Changement saisonnier des quatre roues', 'Seizoenswissel van de vier wielen', 'Seasonal change of all four wheels', 'Pose de vos roues d''été ou d''hiver, serrage au couple et réglage des pressions. Les roues déposées vous sont rendues propres.', 'Montage van uw zomer- of winterwielen, aanhalen met het juiste koppel en afstellen van de spanning. De gedemonteerde wielen krijgt u proper terug.', 'Fitting of your summer or winter wheels, torque tightening and pressure setting. The removed wheels are returned to you clean.', 45, 48.76, NULL::NUMERIC),
          ('CREVAISON', 'PNEUMATIQUE', 'Réparation d''une crevaison', 'Herstelling van een lekke band', 'Puncture repair', 'Le pneu est démonté et réparé par l''intérieur quand la perforation le permet. Sinon, nous vous proposons un remplacement.', 'De band wordt gedemonteerd en van binnenuit hersteld als het gat dat toelaat. Anders stellen we een vervanging voor.', 'The tyre is removed and repaired from the inside when the puncture allows it. Otherwise we suggest a replacement.', 25, 28.10, NULL::NUMERIC),
          ('GEOMETRIE', 'PNEUMATIQUE', 'Géométrie et parallélisme', 'Uitlijning', 'Wheel alignment', 'Réglage des angles des roues avant au banc. Une géométrie juste évite l''usure inégale des pneus et une voiture qui tire d''un côté.', 'Afstelling van de hoeken van de voorwielen op de testbank. Een juiste uitlijning voorkomt ongelijke bandenslijtage en een wagen die naar één kant trekt.', 'Front wheel angles are set on the alignment bench. Correct alignment prevents uneven tyre wear and a car that pulls to one side.', 60, 73.55, NULL::NUMERIC),
          ('DIAG_ELEC', 'DIAGNOSTIC', 'Diagnostic électronique', 'Elektronische diagnose', 'Electronic diagnosis', 'Lecture des codes défaut de tous les calculateurs, explication de chaque défaut et devis si une réparation s''impose.', 'Uitlezen van de foutcodes van alle rekeneenheden, uitleg bij elke fout en een offerte als een herstelling nodig is.', 'Reading of fault codes from all control units, an explanation of each fault and a quote if a repair is needed.', 30, 53.72, NULL::NUMERIC),
          ('CONTROLE_BATTERIE', 'DIAGNOSTIC', 'Contrôle de la batterie et du circuit de charge', 'Controle van accu en laadcircuit', 'Battery and charging system check', 'Test de la batterie, de l''alternateur et du démarreur. Utile avant l''hiver ou après des démarrages difficiles.', 'Test van accu, dynamo en startmotor. Nuttig voor de winter of na moeilijk starten.', 'Test of the battery, alternator and starter motor. Useful before winter or after hard starting.', 15, 20.66, NULL::NUMERIC),
          ('REMPLACEMENT_BATTERIE', 'DIAGNOSTIC', 'Remplacement de la batterie', 'Vervanging van de accu', 'Battery replacement', 'Pose d''une batterie neuve de 72 Ah et contrôle du circuit de charge. L''ancienne batterie reste au garage, qui la confie à la filière de reprise.', 'Plaatsing van een nieuwe accu van 72 Ah en controle van het laadcircuit. De oude accu blijft in de garage, die ze aan de inzamelketen toevertrouwt.', 'Fitting of a new 72 Ah battery and a charging system check. The old battery stays at the garage, which hands it over for recycling.', 30, 138.84, 41.32),
          ('AMPOULES_PHARES', 'DIAGNOSTIC', 'Remplacement des ampoules de phares', 'Vervanging van de koplamplampen', 'Headlight bulb replacement', 'Les deux ampoules de feux de croisement sont remplacées, puis la hauteur des faisceaux est contrôlée.', 'De twee dimlichtlampen worden vervangen, daarna wordt de hoogte van de lichtbundels gecontroleerd.', 'Both dipped beam bulbs are replaced, then the beam height is checked.', 30, 44.63, NULL::NUMERIC),
          ('BALAIS_ESSUIE_GLACE', 'DIAGNOSTIC', 'Remplacement des balais d''essuie-glace', 'Vervanging van de ruitenwisserbladen', 'Wiper blade replacement', 'Pose de balais avant neufs adaptés à votre pare-brise. Des balais usés laissent des traînées et font du bruit.', 'Plaatsing van nieuwe wisserbladen vooraan die bij uw voorruit passen. Versleten bladen laten strepen na en maken lawaai.', 'Fitting of new front blades suited to your windscreen. Worn blades leave streaks and make noise.', 15, 39.67, 24.79),
          ('RECHARGE_CLIM', 'CLIMATISATION', 'Recharge de la climatisation', 'Bijvullen van de airco', 'Air conditioning recharge', 'Récupération du fluide, contrôle de l''étanchéité du circuit et recharge à la quantité prévue par le constructeur.', 'Opvangen van het koelmiddel, controle van de dichtheid van het circuit en bijvullen tot de hoeveelheid van de constructeur.', 'Recovery of the refrigerant, a leak check of the system and recharge to the manufacturer''s quantity.', 60, 98.35, NULL::NUMERIC),
          ('DESINFECTION_CLIM', 'CLIMATISATION', 'Désinfection du circuit de climatisation', 'Ontsmetting van het aircocircuit', 'Air conditioning disinfection', 'Traitement du circuit et de l''évaporateur contre les bactéries et les mauvaises odeurs. Conseillée une fois par an.', 'Behandeling van het circuit en de verdamper tegen bacteriën en slechte geuren. Eén keer per jaar aangeraden.', 'Treatment of the system and evaporator against bacteria and bad smells. Recommended once a year.', 30, 39.67, NULL::NUMERIC),
          ('KIT_DISTRIBUTION', 'MOTEUR', 'Remplacement du kit de distribution', 'Vervanging van de distributieset', 'Timing belt kit replacement', 'Courroie, galets et pompe à eau sont remplacés ensemble, aux intervalles du constructeur. Une courroie qui casse peut détruire le moteur.', 'Riem, rollen en waterpomp worden samen vervangen, volgens de intervallen van de constructeur. Een riem die breekt kan de motor vernielen.', 'Belt, pulleys and water pump are replaced together at the manufacturer''s intervals. A broken belt can destroy the engine.', 240, 474.38, 269.42),
          ('EMBRAYAGE', 'MOTEUR', 'Remplacement de l''embrayage', 'Vervanging van de koppeling', 'Clutch replacement', 'Disque, mécanisme et butée sont remplacés. À envisager quand la pédale devient dure ou que l''embrayage patine.', 'Plaat, drukgroep en druklager worden vervangen. Te overwegen als het pedaal zwaar wordt of de koppeling slipt.', 'Disc, pressure plate and release bearing are replaced. Worth considering when the pedal gets heavy or the clutch slips.', 300, 564.46, 334.71),
          ('RETOUCHE_PEINTURE', 'CARROSSERIE', 'Retouche de peinture', 'Lakherstelling', 'Paint touch-up', 'Rayure ou éclat de peinture traité localement, à la teinte de votre voiture. Le prix vaut pour une zone de la taille d''une main.', 'Kras of lakschade plaatselijk hersteld, in de kleur van uw wagen. De prijs geldt voor een zone ter grootte van een hand.', 'A scratch or chip is treated locally, matched to your car''s colour. The price covers an area the size of a hand.', 60, 90.08, NULL::NUMERIC),
          ('RENOVATION_OPTIQUES', 'CARROSSERIE', 'Rénovation des optiques de phares', 'Renovatie van de koplampen', 'Headlight restoration', 'Les optiques jaunies sont poncées, polies puis protégées. L''éclairage retrouve sa portée.', 'Vergeelde koplampen worden geschuurd, gepolijst en beschermd. De verlichting krijgt haar bereik terug.', 'Yellowed headlight lenses are sanded, polished and protected. The lights regain their reach.', 45, 56.20, NULL::NUMERIC),
          ('PREPARATION_CT', 'CT', 'Préparation au contrôle technique', 'Voorbereiding op de keuring', 'MOT preparation', 'Les points vérifiés au contrôle technique sont passés en revue avant votre rendez-vous. Vous savez ce qui doit être corrigé pour ne pas devoir y retourner.', 'De punten die op de keuring gecontroleerd worden, worden vooraf nagekeken. U weet wat hersteld moet worden om niet terug te moeten.', 'The points checked at the roadworthiness test are reviewed before your appointment. You know what to fix so you do not have to go back.', 30, 44.63, NULL::NUMERIC)
     ) AS v(code, cat, fr, nl, en, dfr, dnl, den, duree, prix, pose)
         JOIN categorie c ON c.code = v.cat
WHERE NOT EXISTS (SELECT 1 FROM service s WHERE s.code = v.code);

-- Composition : pièces consommées quand le garage les fournit (V76).
INSERT INTO composition_prestation (service_id, piece_id, quantite, created_by, updated_by)
SELECT s.id, p.id, v.quantite, 'demo', 'demo'
FROM (VALUES
          ('VIDANGE_STD', 'FH-1042', 1),
          ('VIDANGE_STD', 'BB-P080', 4),
          ('VIDANGE_STD', 'BB-P005', 1),
          ('REVISION_ANNUELLE', 'FH-1042', 1),
          ('REVISION_ANNUELLE', 'BB-P080', 4),
          ('REVISION_ANNUELLE', 'FA-2201', 1),
          ('REVISION_ANNUELLE', 'BB-P001', 1),
          ('REVISION_ANNUELLE', 'BB-P005', 1),
          ('REVISION_COMPLETE', 'FH-1042', 1),
          ('REVISION_COMPLETE', 'BB-P080', 4),
          ('REVISION_COMPLETE', 'FA-2201', 1),
          ('REVISION_COMPLETE', 'BB-P001', 1),
          ('REVISION_COMPLETE', 'BB-P003', 1),
          ('REVISION_COMPLETE', 'BB-P005', 1),
          ('FILTRE_AIR', 'FA-2201', 1),
          ('FILTRE_HABITACLE', 'BB-P001', 1),
          ('BOUGIES', 'BB-P020', 4),
          ('LIQUIDE_REFROIDISSEMENT', 'BB-P081', 5),
          ('PURGE_FREIN', 'BB-P082', 1),
          ('PLAQUETTES_AV', 'PL-3310', 1),
          ('PLAQUETTES_AR', 'BB-P010', 1),
          ('DISQUES_PLAQUETTES_AV', 'BB-P011', 1),
          ('DISQUES_PLAQUETTES_AV', 'PL-3310', 1),
          ('DISQUES_PLAQUETTES_AR', 'BB-P012', 1),
          ('DISQUES_PLAQUETTES_AR', 'BB-P010', 1),
          ('MONTAGE_PNEU', 'BB-P061', 1),
          ('REMPLACEMENT_BATTERIE', 'BT-7201', 1),
          ('AMPOULES_PHARES', 'BB-P050', 1),
          ('BALAIS_ESSUIE_GLACE', 'BB-P054', 1),
          ('KIT_DISTRIBUTION', 'BB-P030', 1),
